<?php $formIssue=$editIssue??null;$selectedAssignees=array_map(fn($row)=>(int)$row['id'],$formIssue['assignees']??[]);$selectedLabels=array_map(fn($row)=>(int)$row['id'],$formIssue['labels']??[]); ?>
<form class="form-grid work-issue-form" method="post" action="<?= e($issueFormAction) ?>"><?= csrf_field() ?><?php if($formIssue): ?><input type="hidden" name="version" value="<?= e($formIssue['version']) ?>"><?php endif; ?><input type="hidden" name="assignees_present" value="1"><input type="hidden" name="labels_present" value="1"><label class="full">Work item title<input name="title" value="<?= e($formIssue['title']??'') ?>" maxlength="250" placeholder="What needs to happen?" required></label><label class="full">Description<span class="work-editor-toolbar"><button type="button" class="quiet" data-work-format="bold">Bold</button><button type="button" class="quiet" data-work-format="heading">Heading</button><button type="button" class="quiet" data-work-format="list">List</button><small>Markdown supported as source</small></span><textarea name="description" data-work-markdown rows="5" maxlength="30000"><?= e($formIssue['description']??'') ?></textarea></label><label>Type<select name="issue_type"><?php foreach(WorkService::TYPES as $value=>$label): ?><option value="<?= $value ?>" <?= ($formIssue['issue_type']??'task')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Fix version<select name="fix_version_id"><option value="">No release</option><?php foreach($releases as $release): ?><option value="<?= e($release['id']) ?>" <?= ($formIssue['fix_version_id']??'')==$release['id']?'selected':'' ?>><?= e($release['name']) ?> / <?= e(WorkReleaseService::STATUSES[$release['status']]) ?></option><?php endforeach; ?></select></label><label>State<select name="state_id"><?php foreach($states as $state): ?><option value="<?= e($state['id']) ?>" <?= ($formIssue['state_id']??($states[1]['id']??$states[0]['id']))==$state['id']?'selected':'' ?>><?= e($state['name']) ?></option><?php endforeach; ?></select></label><label>Priority<select name="priority"><?php foreach(WorkService::PRIORITIES as $key=>$label): ?><option value="<?= $key ?>" <?= (int)($formIssue['priority']??0)===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Assignees<select name="assignee_ids[]" multiple size="3"><?php foreach($people as $person):if(!$person['active']&&!in_array((int)$person['id'],$selectedAssignees,true))continue; ?><option value="<?= e($person['id']) ?>" <?= in_array((int)$person['id'],$selectedAssignees,true)?'selected':'' ?>><?= e($person['name']) ?><?= !$person['active']?' (inactive)':'' ?></option><?php endforeach; ?></select><small>Use Ctrl / Cmd to select more than one.</small></label><label>Labels<select name="label_ids[]" multiple size="3"><?php foreach($labels as $label): ?><option value="<?= e($label['id']) ?>" <?= in_array((int)$label['id'],$selectedLabels,true)?'selected':'' ?>><?= e($label['name']) ?></option><?php endforeach; ?></select><?php if(!$labels): ?><small>Add labels in project Settings.</small><?php endif; ?></label><label>Cycle<select name="cycle_id"><option value="">No cycle</option><?php foreach($cycles as $cycle): ?><option value="<?= e($cycle['id']) ?>" <?= ($formIssue['cycle_id']??'')==$cycle['id']?'selected':'' ?>><?= e($cycle['name']) ?></option><?php endforeach; ?></select></label><label>Module<select name="module_id"><option value="">No module</option><?php foreach($modules as $module): ?><option value="<?= e($module['id']) ?>" <?= ($formIssue['module_id']??'')==$module['id']?'selected':'' ?>><?= e($module['name']) ?></option><?php endforeach; ?></select></label><label>Start date<input name="start_date" type="date" value="<?= e($formIssue['start_date']??'') ?>"></label><label>Due date<input name="due_date" type="date" value="<?= e($formIssue['due_date']??'') ?>"></label><label>Estimate (points)<input name="estimate" type="number" min="0" max="1000" step="0.5" value="<?= e($formIssue['estimate']??'') ?>"></label><label>Parent work item<select name="parent_id"><option value="">No parent</option><?php $parentChoices=Db::all('SELECT id,sequence,title FROM work_issues WHERE project_id=? AND deleted_at IS NULL AND id<>? ORDER BY sequence DESC LIMIT 500',[$project['id'],$formIssue['id']??0]);if(!empty($formIssue['parent_id'])&&!in_array((int)$formIssue['parent_id'],array_map(fn($row)=>(int)$row['id'],$parentChoices),true)){$parentRow=Db::one('SELECT id,sequence,title FROM work_issues WHERE project_id=? AND id=?',[$project['id'],$formIssue['parent_id']]);if($parentRow)$parentChoices[]=$parentRow;}foreach($parentChoices as $choice): ?><option value="<?= e($choice['id']) ?>" <?= ($formIssue['parent_id']??($newParent??''))==$choice['id']?'selected':'' ?>><?= e($project['identifier'].'-'.$choice['sequence'].' - '.$choice['title']) ?></option><?php endforeach; ?></select></label><?php if(!$formIssue): ?><label class="full">Create in<select name="intake_status"><option value="accepted">Project work items</option><option value="pending">Intake · needs triage</option></select></label><?php endif; ?><div class="full work-form-actions"><button><?= $formIssue?'Save work item':'Create work item' ?></button><span class="footnote">Stored locally. No email or external message is sent.</span></div></form>
